class Religion {
  const Religion(this.key, this.en, this.ar, this.fr);
  final String key;
  final String en;
  final String ar;
  final String fr;
  String label(String lang) => pickLang(lang, ar, en, fr);
  List<Sect> get sects => [for (final s in kSects) if (s.religion == key) s];
}

class Sect {
  const Sect(this.religion, this.key, this.en, this.ar, this.fr);
  final String religion;
  final String key;
  final String en;
  final String ar;
  final String fr;
  String label(String lang) => pickLang(lang, ar, en, fr);
}

